mapper.select:
SELECT fb.id, fb.message_id, left(m.session_id::text, 8) AS session_key, s.scenario_id, sc.title AS scenario_title, fb.rating, fb.comment, fb.comment_ciphertext, fb.comment_key_id, fb.comment_encryption_version, fb.created_at FROM chat_feedback fb JOIN chat_message m ON m.id = fb.message_id JOIN chat_session s ON s.id = m.session_id JOIN scenario sc ON sc.id = s.scenario_id
fb.rating = #{rating}
ORDER BY fb.created_at DESC, fb.id DESC LIMIT #{limit}

mapper.update:
UPDATE chat_feedback
SET comment = #{comment},
    comment_ciphertext = #{commentCiphertext},
    comment_key_id = #{commentKeyId},
    comment_encryption_version = #{commentEncryptionVersion}
WHERE id = #{id}
